/**
 * MrStockd core schema.
 *
 * Auth tables (users, sessions, organizations) are generated by Better Auth
 * and added in a later migration. `ownerId` columns below hold the Better
 * Auth user or organization id.
 *
 * Money columns are integer cents. Vector search uses pgvector; run
 * `CREATE EXTENSION IF NOT EXISTS vector;` once before the first migration.
 */
import {
  boolean,
  index,
  integer,
  jsonb,
  pgEnum,
  pgTable,
  text,
  timestamp,
  uniqueIndex,
  uuid,
  vector,
} from "drizzle-orm/pg-core";

const timestamps = {
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
};

export const listingStatus = pgEnum("listing_status", ["draft", "in_review", "live", "rejected", "paused"]);
export const pricingModel = pgEnum("pricing_model", ["credits", "subscription"]);
export const orderStatus = pgEnum("order_status", ["created", "approved", "completed", "refunded", "failed"]);
export const buyerKind = pgEnum("buyer_kind", ["human", "agent"]);

export const sellers = pgTable("sellers", {
  id: uuid("id").primaryKey().defaultRandom(),
  ownerId: text("owner_id").notNull(),
  displayName: text("display_name").notNull(),
  /** PayPal merchant id from multiparty onboarding. */
  paypalMerchantId: text("paypal_merchant_id"),
  /** True only once PayPal reports the seller can receive payments. */
  payoutsEnabled: boolean("payouts_enabled").notNull().default(false),
  ...timestamps,
}, (t) => [uniqueIndex("sellers_owner_idx").on(t.ownerId)]);

export const listings = pgTable("listings", {
  id: uuid("id").primaryKey().defaultRandom(),
  sellerId: uuid("seller_id").notNull().references(() => sellers.id),
  slug: text("slug").notNull(),
  name: text("name").notNull(),
  summary: text("summary").notNull(),
  description: text("description").notNull(),
  /** Seller's upstream endpoint. Validated by the SSRF guard on save and on every call. */
  endpointUrl: text("endpoint_url").notNull(),
  /** Seller's upstream credential, encrypted with AES-256-GCM (iv:tag:ciphertext). */
  upstreamSecretEnc: text("upstream_secret_enc"),
  pricingModel: pricingModel("pricing_model").notNull(),
  /** Price per credit pack, or per month for subscriptions. */
  unitPriceCents: integer("unit_price_cents").notNull(),
  creditsPerUnit: integer("credits_per_unit").notNull().default(1),
  paypalPlanId: text("paypal_plan_id"),
  status: listingStatus("status").notNull().default("draft"),
  vettingReport: jsonb("vetting_report"),
  embedding: vector("embedding", { dimensions: 1536 }),
  ...timestamps,
}, (t) => [
  uniqueIndex("listings_slug_idx").on(t.slug),
  index("listings_seller_idx").on(t.sellerId),
  index("listings_embedding_idx").using("hnsw", t.embedding.op("vector_cosine_ops")),
]);

export const orders = pgTable("orders", {
  id: uuid("id").primaryKey().defaultRandom(),
  buyerId: text("buyer_id").notNull(),
  buyerKind: buyerKind("buyer_kind").notNull().default("human"),
  /** Set when an agent placed the order on the buyer's behalf. */
  agentId: uuid("agent_id"),
  listingId: uuid("listing_id").notNull().references(() => listings.id),
  quantity: integer("quantity").notNull(),
  subtotalCents: integer("subtotal_cents").notNull(),
  platformFeeCents: integer("platform_fee_cents").notNull(),
  sellerPayoutCents: integer("seller_payout_cents").notNull(),
  currency: text("currency").notNull().default("USD"),
  paypalOrderId: text("paypal_order_id"),
  /** Sent as PayPal-Request-Id so retries never create a second order. */
  paypalRequestId: uuid("paypal_request_id").notNull().defaultRandom(),
  status: orderStatus("status").notNull().default("created"),
  ...timestamps,
}, (t) => [
  uniqueIndex("orders_paypal_order_idx").on(t.paypalOrderId),
  index("orders_buyer_idx").on(t.buyerId),
]);

/** Agents a buyer has authorized to shop for them, with server-enforced spend limits. */
export const agents = pgTable("agents", {
  id: uuid("id").primaryKey().defaultRandom(),
  ownerId: text("owner_id").notNull(),
  name: text("name").notNull(),
  /** Purchases above this need human approval in PayPal. */
  approvalThresholdCents: integer("approval_threshold_cents").notNull().default(0),
  monthlyBudgetCents: integer("monthly_budget_cents").notNull().default(2000),
  revokedAt: timestamp("revoked_at", { withTimezone: true }),
  ...timestamps,
});

export const apiKeys = pgTable("api_keys", {
  id: uuid("id").primaryKey().defaultRandom(),
  ownerId: text("owner_id").notNull(),
  listingId: uuid("listing_id").notNull().references(() => listings.id),
  orderId: uuid("order_id").references(() => orders.id),
  prefix: text("prefix").notNull(),
  /** SHA-256 of the full key. The key itself is never stored. */
  keyHash: text("key_hash").notNull(),
  creditsRemaining: integer("credits_remaining").notNull().default(0),
  revokedAt: timestamp("revoked_at", { withTimezone: true }),
  lastUsedAt: timestamp("last_used_at", { withTimezone: true }),
  ...timestamps,
}, (t) => [
  uniqueIndex("api_keys_prefix_idx").on(t.prefix),
  index("api_keys_owner_idx").on(t.ownerId),
]);

export const usageEvents = pgTable("usage_events", {
  id: uuid("id").primaryKey().defaultRandom(),
  apiKeyId: uuid("api_key_id").notNull().references(() => apiKeys.id),
  listingId: uuid("listing_id").notNull().references(() => listings.id),
  creditsUsed: integer("credits_used").notNull().default(1),
  statusCode: integer("status_code").notNull(),
  latencyMs: integer("latency_ms").notNull(),
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
}, (t) => [index("usage_events_listing_time_idx").on(t.listingId, t.createdAt)]);

/** Every PayPal webhook event id is recorded once; repeats are ignored. */
export const paypalWebhookEvents = pgTable("paypal_webhook_events", {
  eventId: text("event_id").primaryKey(),
  eventType: text("event_type").notNull(),
  payload: jsonb("payload").notNull(),
  processedAt: timestamp("processed_at", { withTimezone: true }),
  receivedAt: timestamp("received_at", { withTimezone: true }).notNull().defaultNow(),
});

/** Append-only record of money and key events. Never update or delete rows. */
export const auditLog = pgTable("audit_log", {
  id: uuid("id").primaryKey().defaultRandom(),
  actorId: text("actor_id"),
  actorKind: text("actor_kind").notNull(),
  action: text("action").notNull(),
  subjectType: text("subject_type").notNull(),
  subjectId: text("subject_id").notNull(),
  metadata: jsonb("metadata"),
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
}, (t) => [index("audit_log_subject_idx").on(t.subjectType, t.subjectId)]);
